/* Supplier evidence work queue and interactive accounts summary. */
window.FareAccounts={create(deps){
  'use strict';
  const {B,esc,icon,btn,modal,detailModal,change,getProfile:p,getYear:y,pounds,plain,displayDate,defaultDate,categoryName,entry,invoiceForm,render,toast}=deps;
  const q=s=>document.querySelector(s);
  const field=(label,name,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
  function pendingView(){
    const groups=B.supplierProofGroups(p(),y().end),total=B.sum(groups.map(g=>g.remaining));
    return `<div class="banner ${total?'orange':''}"><span class="banner-text">${icon('invoice')}<strong>${pounds(total)} awaiting invoices</strong> · Supplier payments are held separately until supported.</span></div>${groups.length?groups.map(g=>`<div class="card"><div class="card-header"><div><h2>${esc(categoryName(g.categoryId))}</h2><p>${g.transactions.length} payments · ${pounds(g.remaining)} still uncovered</p></div>${btn('cover-supplier','Add / match covering invoice','invoice','primary',`data-id="${esc(g.categoryId)}"`)}</div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Details</th><th>Bank / cash account</th><th class="right">Payment</th><th class="right">Still needs invoice</th></tr></thead><tbody>${g.transactions.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(0,100).map(t=>`<tr><td>${displayDate(t.date)}</td><td class="details"><strong>${esc(t.description)}</strong><small>${B.periodOf(y(),t.date)==='previous'?'Carried from a previous period':t.reconciled?'Bank reconciled · invoice still required':'Awaiting supplier invoice'}</small></td><td class="muted">${esc(B.account(p(),t.accountId)?.name)}</td><td class="right">${pounds(-t.amount)}</td><td class="right">${pounds(t.remaining)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${g.transactions.length>100?'Showing first 100 payments; the matching window includes all payments.':'One invoice may cover several payments, or several invoices may cover one payment.'}</span><strong>${pounds(g.remaining)}</strong></div></div>`).join(''):`<div class="card"><div class="empty">${icon('check')}<h2>No supplier payments waiting for invoices.</h2><p>New supplier payments will appear here until you match their supporting invoices.</p></div></div>`}`;
  }
  function coverDialog(categoryId,invoiceId=null){
    const category=B.account(p(),categoryId);if(!category||!B.isSupplierAccount(p(),categoryId))throw new Error('Select a supplier subaccount.');
    const rows=B.pendingSupplierPayments(p()).filter(t=>t.categoryId===categoryId&&t.date<=y().end),invoices=p().invoices.filter(i=>i.kind==='purchase'&&B.invoiceControl(p(),i)===categoryId&&B.invoiceBalance(p(),i)>0);
    if(!rows.length){detailModal('No uncovered payments','<p>This supplier account has no bank/cash payments waiting for invoices.</p>');return;}
    const unlocked=rows.filter(t=>!B.yearAt(p(),t.date)?.locked),total=B.sum(unlocked.map(t=>t.remaining)),contacts=[...new Set(rows.map(t=>t.contactId).filter(Boolean))],supplier=contacts.length===1?p().contacts.find(c=>c.id===contacts[0])?.name:category.name+' suppliers';
    const latest=rows.reduce((d,t)=>t.date>d?t.date:d,rows[0].date),chosen=invoices.find(i=>i.id===invoiceId);
    modal('Cover supplier payments',`<div class="notice"><strong>${esc(categoryName(categoryId))}</strong> · ${pounds(B.sum(rows.map(t=>t.remaining)))} uncovered. Select payments and amounts below. One invoice can cover the whole balance, or just part of it.</div><div class="form-grid"><label class="field full">How would you like to cover them?<select name="coverMode"><option value="new" ${chosen?'':'selected'}>Enter one covering invoice / supplier statement</option><option value="existing" ${chosen?'selected':''}>Match an invoice already entered</option></select></label><div class="form-grid full" id="cover-new">${field('Supplier / statement issuer','supplier',supplier||'', 'required maxlength="100"')}${field('Invoice date','invoiceDate',latest,'required placeholder="DD/MM/YYYY or DDMMYY"')}${field('Reference (optional)','reference','','maxlength="100" placeholder="Generated if blank"')}${field('Invoice total (£)','invoiceTotal',plain(total),'type="number" required min="0.01" step="0.01"')}${field('Business use (%)','businessPercent',100,'type="number" required min="0" max="100" step="0.01"')}${!category.expenseCategoryId?`<label class="field">Expense category<select name="expenseCategoryId">${p().accounts.filter(a=>a.type==='expense').map(a=>`<option value="${esc(a.id)}" ${a.id==='fuel'?'selected':''}>${esc(categoryName(a.id))}</option>`).join('')}</select></label>`:''}</div><label class="field full" id="cover-existing" hidden>Existing invoice<select name="invoiceId"><option value="">Choose an invoice</option>${invoices.map(i=>`<option value="${esc(i.id)}" ${i.id===invoiceId?'selected':''}>${esc(i.reference)} · ${esc(p().contacts.find(c=>c.id===i.contactId)?.name)} · ${pounds(B.invoiceBalance(p(),i))} outstanding</option>`).join('')}</select></label></div><div class="allocation-toolbar"><label class="check-label"><input type="checkbox" id="cover-select-all" checked>Select all open-period payments</label><strong id="cover-total">${pounds(total)} selected</strong></div><div class="allocation-table table-wrap"><table><thead><tr><th>Use</th><th>Date / payment</th><th class="right">Uncovered</th><th>Amount covered (£)</th></tr></thead><tbody>${rows.map(t=>`<tr><td><input type="checkbox" data-cover-payment="${esc(t.id)}" ${B.yearAt(p(),t.date)?.locked?'disabled':'checked'} aria-label="Select ${esc(t.description)}"></td><td class="details"><strong>${esc(t.description)}</strong><small>${displayDate(t.date)}${B.yearAt(p(),t.date)?.locked?' · locked period':''}</small></td><td class="right">${pounds(t.remaining)}</td><td><input type="number" data-cover-amount="${esc(t.id)}" value="${plain(t.remaining)}" min="0.01" max="${plain(t.remaining)}" step="0.01" ${B.yearAt(p(),t.date)?.locked?'disabled':''} aria-label="Amount covered for ${esc(t.description)}"></td></tr>`).join('')}</tbody></table></div><div class="notice" id="cover-status"></div>`,'Save and match',async(f,form)=>{
      const allocations=rows.filter(t=>form.querySelector(`[data-cover-payment="${t.id}"]`).checked&&!B.yearAt(p(),t.date)?.locked).map(t=>({transactionId:t.id,amount:B.money(form.querySelector(`[data-cover-amount="${t.id}"]`).value)}));
      await change(()=>{if(f.get('coverMode')==='existing')B.allocateSupplierPayments(p(),f.get('invoiceId'),allocations);else{const d=B.date(f.get('invoiceDate'));B.ensureFinancialPeriod(p(),d);B.coveringSupplierInvoice(p(),{categoryId,supplier:String(f.get('supplier')).trim(),date:d,reference:String(f.get('reference')).trim(),amount:B.money(f.get('invoiceTotal')),businessPercent:Number(f.get('businessPercent')),expenseCategoryId:f.get('expenseCategoryId')||undefined,allocations});}},'Supplier invoice matched. Uncovered amounts remain in the queue.');
    });
    const form=q('#modal-form');let totalEdited=false;
    function sumSelected(){return B.sum(rows.filter(t=>form.querySelector(`[data-cover-payment="${t.id}"]`).checked&&!B.yearAt(p(),t.date)?.locked).map(t=>{try{return B.money(form.querySelector(`[data-cover-amount="${t.id}"]`).value);}catch{return 0;}}));}
    function update(){const amount=sumSelected(),existing=form.elements.coverMode.value==='existing';q('#cover-new').hidden=existing;q('#cover-existing').hidden=!existing;q('#cover-new').querySelectorAll('input,select').forEach(el=>el.disabled=existing);q('#cover-total').textContent=pounds(amount)+' selected';if(!existing&&!totalEdited)form.elements.invoiceTotal.value=plain(amount);let invoiceAmount;try{invoiceAmount=existing?B.invoiceBalance(p(),p().invoices.find(i=>i.id===form.elements.invoiceId.value)):B.money(form.elements.invoiceTotal.value);}catch{invoiceAmount=0;}q('#cover-status').textContent=amount>invoiceAmount?`Selected amount exceeds the invoice by ${pounds(amount-invoiceAmount)}. Reduce the selected coverage or correct the invoice total.`:`${pounds(amount)} will be matched. ${pounds(Math.max(0,invoiceAmount-amount))} of the invoice will remain outstanding. Bank amounts and reconciliations are preserved.`;rows.forEach(t=>{form.querySelector(`[data-cover-amount="${t.id}"]`).disabled=!form.querySelector(`[data-cover-payment="${t.id}"]`).checked||!!B.yearAt(p(),t.date)?.locked;});}
    form.elements.invoiceTotal.addEventListener('input',()=>totalEdited=true);q('#cover-select-all').addEventListener('change',e=>{form.querySelectorAll('[data-cover-payment]:not(:disabled)').forEach(el=>el.checked=e.target.checked);update();});form.addEventListener('input',update);form.addEventListener('change',update);form.elements.invoiceDate.addEventListener('blur',()=>{try{const iso=B.date(form.elements.invoiceDate.value);form.elements.invoiceDate.value=`${iso.slice(8)}/${iso.slice(5,7)}/${iso.slice(0,4)}`;form.elements.invoiceDate.setCustomValidity('');}catch(e){form.elements.invoiceDate.setCustomValidity(e.message);}});update();
  }
  function summaryView(){const summary=B.accountsSummary(p(),y());
    const status=summary.pendingAmount?`<div class="banner orange"><span class="banner-text">${icon('invoice')}<strong>Draft accounts · ${pounds(summary.pendingAmount)} awaiting invoices</strong></span>${btn('show-awaiting','Review supplier payments','arrow','small')}</div>`:summary.uncategorised?`<div class="banner orange">${summary.uncategorised} transactions still need a category.</div>`:`<div class="banner"><span class="banner-text">${icon('check')}Supplier payments are supported. Your accounts are ready for review.</span></div>`;
    return `${status}<div class="accounts-kpis"><div><small>Income</small><strong>${pounds(summary.revenue)}</strong></div><div><small>Cost of sales</small><strong>${pounds(summary.costSales)}</strong></div><div><small>Gross profit</small><strong>${pounds(summary.grossProfit)}</strong></div><div><small>Net profit before tax</small><strong>${pounds(summary.profit)}</strong></div></div><div class="accounts-summary">${summary.sections.map(s=>`<div class="card"><div class="card-header"><div><h2>${esc(s.name)}</h2><p>${s.type==='income'?'Money earned':s.type==='expense'?'Business costs':s.id==='suppliers'?'Verified supplier balances · unmatched payments listed separately':s.type==='asset'?'What the business holds':s.type==='equity'?'Owner funds and drawings':'What the business owes'}</p></div>${btn('section-subcategory','Add subcategory','plus','small',`data-id="${esc(s.id)}"`)}</div><div class="section-list">${s.rows.filter(a=>a.parent||a.amount||a.id!==s.rootId).map(a=>`<button type="button" class="account-summary-row" data-action="account-detail" data-id="${esc(a.id)}"><span>${esc(a.name)}<small>${esc(a.parent?B.account(p(),a.parent)?.name:'')}</small></span><strong>${pounds(a.amount)}</strong>${icon('chevron')}</button>`).join('')||'<p class="muted" style="font-size:12px">Add a subcategory or click Add section to organise these accounts.</p>'}<div class="report-total"><span>Total ${esc(s.name.toLowerCase())}</span><span>${pounds(s.total)}</span></div></div></div>`).join('')}</div><div class="actions">${btn('add-accounts-section','Add section','plus','primary')}</div><div class="notice">Click a subcategory to inspect its records or add a transaction or invoice. Income, cost of sales and expenses show the selected period’s ${p().basis==='cash'?'cash-basis':'accrual'} result; assets, liabilities and capital show balances at year end. Supplier payments without invoices are held in the review queue.</div>`;
  }
  function accountDetail(id){const a=B.account(p(),id);if(!a){if(id==='unverified-supplier-payments')deps.showAwaiting();return;}
    const from=['income','expense'].includes(a.type)?y().start:'0000-01-01',rows=B.entries(p()).filter(e=>e.date>=from&&e.date<=y().end).flatMap(e=>e.lines.filter(l=>l.accountId===id&&l.amount).map(l=>({date:e.date,description:e.description,amount:l.amount}))),invoices=p().invoices.filter(i=>i.date<=y().end&&(i.categoryId===id||B.invoiceControl(p(),i)===id));
    detailModal(esc(categoryName(id)),`<p class="muted">${['income','expense'].includes(a.type)?'Activity this financial period':'Ledger through year end'} · ${displayDate(y().end)}</p>${B.isSupplierAccount(p(),id)?`<div class="notice orange">${pounds(B.sum(B.pendingSupplierPayments(p(),y().end).filter(t=>t.categoryId===id).map(t=>t.remaining)))} awaiting invoices.</div>`:''}<div class="allocation-table table-wrap"><table><thead><tr><th>Date / details</th><th class="right">Debit</th><th class="right">Credit</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="details"><strong>${esc(r.description)}</strong><small>${displayDate(r.date)}</small></td><td class="right">${r.amount>0?pounds(r.amount):'—'}</td><td class="right">${r.amount<0?pounds(-r.amount):'—'}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">No records yet.</td></tr>'}</tbody></table></div>${invoices.length?`<h3 style="margin-top:18px">Invoices / receipts</h3>${invoices.map(i=>`<div class="report-row"><span>${esc(i.reference)} · ${displayDate(i.date)}</span><strong>${pounds(i.amount)}</strong></div>`).join('')}`:' '}`,btn('account-add-transaction','Add transaction','plus','primary',`data-id="${esc(id)}"`)+(['expense','income'].includes(a.type)||B.isSupplierAccount(p(),id)?btn('account-add-invoice','Add invoice / receipt','invoice','',`data-id="${esc(id)}"`):'')+(B.isSupplierAccount(p(),id)?btn('cover-supplier','Match supplier payments','check','',`data-id="${esc(id)}"`):''));
  }
  function addTransaction(id){const a=B.account(p(),id);if(!a)return;entry.transaction(a.kind?{accountId:id}:{categoryId:id,direction:a.type==='income'?'receipt':'payment'});}
  function addInvoice(id){const a=B.account(p(),id);if(a?.type==='income')invoiceForm(id);else entry.receipt({categoryId:id});}
  function sectionForm(){modal('Add accounts section',`<div class="form-grid">${field('Section name','name','','required maxlength="100"')}<label class="field">Section type<select name="type"><option value="expense">Costs / expenses</option><option value="income">Income</option><option value="asset">Assets</option><option value="liability">Liabilities</option><option value="equity">Capital / equity</option></select></label><div class="full" id="section-categories"></div></div><div class="notice">Choose existing categories to place in this section, or create an empty section and add subcategories afterwards. Report grouping does not change their ledger values.</div>`,'Create section',async(f,form)=>{const ids=[...form.querySelectorAll('[data-section-account]:checked')].map(el=>el.dataset.sectionAccount);await change(()=>B.addReportSection(p(),f.get('name'),f.get('type'),ids),'Accounts section created');});const form=q('#modal-form');function choices(){q('#section-categories').innerHTML='<label class="field">Existing categories (optional)</label><div class="section-choice-list">'+p().accounts.filter(a=>a.type===form.elements.type.value&&!a.kind&&a.id!=='suspense').map(a=>`<label class="check-label"><input type="checkbox" data-section-account="${esc(a.id)}">${esc(categoryName(a.id))}</label>`).join('')+'</div>';}form.elements.type.addEventListener('change',choices);choices();}
  function sectionSubcategory(sectionId){const s=p().reportSections.find(s=>s.id===sectionId);if(!s?.rootId)return;modal(`Add to ${esc(s.name)}`,field('Subcategory name','name','','required maxlength="100"'),'Add subcategory',async f=>{await change(()=>{const a=B.addSubcategory(p(),s.rootId,f.get('name'));a.reportSectionId=s.id;},'Subcategory added');});}
  function allocationsView(inv){const rows=(p().invoiceAllocations||[]).filter(a=>a.invoiceId===inv.id);return rows.length?`<h3 style="margin-top:20px">Matched supplier payments</h3>${rows.map(a=>{const t=p().transactions.find(t=>t.id===a.transactionId);return `<div class="list-row"><div><h3>${esc(t?.description)}</h3><p>${displayDate(t.date)} · ${pounds(a.amount)} covered</p></div>${btn('remove-allocation','Unmatch','','small',`data-id="${esc(a.id)}"`)}</div>`;}).join('')}`:'';}
  return {pendingView,coverDialog,summaryView,accountDetail,addTransaction,addInvoice,sectionForm,sectionSubcategory,allocationsView};
}};
